@router.get("/admin/tenants/{tenant_id}/export-ddl")
async def export_tenant_ddl(
    tenant_id: str,
    exporter: SchemaExporter = Depends(get_schema_exporter),
    current_user: User = Depends(get_current_user)
):
    if tenant_id != current_user.tenant_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to export DDL for target tenant")
    ddl_script = await exporter.generate_schema_ddl(f"tenant_{tenant_id}")
    return PlainTextResponse(ddl_script, media_type="text/x-sql")
